// qrcode.min.js — minimal QR generator (byte mode, version auto, ECC L/M/Q/H)
// Slim build. Exposes window.QRCode.toCanvas(text, canvasEl, opts)
(function(global){
'use strict';
const EC_LEVELS={L:1,M:0,Q:3,H:2};
const EC_BLOCKS={
1:{L:[1,26],M:[1,26],Q:[1,26],H:[1,26]},
2:{L:[1,44],M:[1,44],Q:[1,44],H:[1,44]},
3:{L:[1,70],M:[1,70],Q:[1,70],H:[1,70]},
4:{L:[1,100],M:[1,100],Q:[1,100],H:[1,100]},
5:{L:[1,134],M:[1,134],Q:[1,134],H:[1,134]},
6:{L:[2,86],M:[2,86],Q:[2,86],H:[2,86]},
7:{L:[2,98],M:[2,98],Q:[2,98],H:[2,98]},
8:{L:[2,121],M:[2,121],Q:[2,121],H:[2,121]},
9:{L:[2,146],M:[2,146],Q:[2,146],H:[2,146]},
10:{L:[2,86,2,87],M:[2,86,2,87],Q:[2,86,2,87],H:[2,86,2,87]}
};
function gfMul(a,b){let p=0;for(let i=0;i<8;i++){if(b&1)p^=a;const hi=a&0x80;a=(a<<1)&0xFF;if(hi)a^=0x1D;b>>=1;}return p;}
const EXP=new Array(256),LOG=new Array(256);
(function(){let x=1;for(let i=0;i<255;i++){EXP[i]=x;LOG[x]=i;x=gfMul(x,2);}EXP[255]=EXP[0];})();
function gfInv(a){return EXP[255-LOG[a]];}
function rsGenPoly(deg){let g=[1];for(let i=0;i<deg;i++){const ng=new Array(g.length+1).fill(0);for(let j=0;j<g.length;j++){ng[j]^=gfMul(g[j],EXP[i]);ng[j+1]^=g[j];}g=ng;}return g;}
function rsEncode(data,ecLen){const gen=rsGenPoly(ecLen);const res=new Array(data.length+ecLen).fill(0);for(let i=0;i<data.length;i++)res[i]=data[i];for(let i=0;i<data.length;i++){const coef=res[i];if(coef===0)continue;for(let j=0;j<gen.length;j++)res[i+j]^=gfMul(gen[j],coef);}return res.slice(data.length);}
function encodeData(text,ecLevel){const bytes=[];for(const ch of unescape(encodeURIComponent(text)))bytes.push(ch.charCodeAt(0));const ec=EC_LEVELS[ecLevel];
// pick smallest version
for(let v=1;v<=10;v++){const [g1,c1,g2,c2]=EC_BLOCKS[v][ecLevel==='L'?'L':'M'];
const totalBlocks=(g1||0)+(g2||0);const totalDataCW=totalBlocks*((c1||0));const cap=totalDataCW-2-2;
const lenBits=bytes.length<256?8:16;const need=4+lenBits+bytes.length*8;const totalBits=totalBlocks*(c1+(v<=10?0:0))*8;
if(bytes.length*8+4+lenBits<=totalDataCW*8){return build(v,bytes,ecLevel,totalDataCW,g1,c1,g2,c2);}}
throw new Error('too long');}
function build(version,bytes,ecLevel,totalDataCW,g1,c1,g2,c2){const size=17+4*version;
const bits=[];const pushBits=(v,n)=>{for(let i=n-1;i>=0;i--)bits.push((v>>i)&1);};
pushBits(4,4);pushBits(bytes.length<256?8:16,bytes.length<256?8:16);if(bytes.length<256){pushBits(bytes.length,8);}else{pushBits(bytes.length,16);}
for(const b of bytes)pushBits(b,8);const totalBits=totalDataCW*8;if(bits.length+4<=totalBits){pushBits(0,Math.min(4,totalBits-bits.length));}while(bits.length%8)bits.push(0);while(bits.length<totalBits)pushBits(0xEC,8);
const dataCW=[];for(let i=0;i<bits.length;i+=8){let b=0;for(let j=0;j<8;j++)b=(b<<1)|bits[i+j];dataCW.push(b);}
// simplified: single block assumption for small payloads
const ecLen=c1;const block=dataCW.slice(0,g1*c1);const ecBytes=rsEncode(block,ecLen);
const codewords=block.concat(ecBytes);
const matrix=Array.from({length:size},()=>new Array(size).fill(0));
const reserved=Array.from({length:size},()=>new Array(size).fill(0));
function setF(r,c,v){if(r>=0&&r<size&&c>=0&&c<size){matrix[r][c]=v?1:0;reserved[r][c]=1;}}
// finders
function finder(r,c){for(let i=-1;i<8;i++)for(let j=-1;j<8;j++){const rr=r+i,cc=c+j;if(rr<0||rr>=size||cc<0||cc>=size)continue;const border=(i>=0&&i<7&&(j===0||j===6))||(j>=0&&j<7&&(i===0||i===6));const core=i>=2&&i<=4&&j>=2&&j<=4;setF(rr,cc,border||core);}}
finder(0,0);finder(0,size-7);finder(size-7,0);
// timing
for(let i=8;i<size-8;i++){setF(6,i,i%2===0);setF(i,6,i%2===0);}
// dark module
setF(size-8,8,1);
// reserve format
for(let i=0;i<9;i++){if(!reserved[8][i])setF(8,i,0);if(!reserved[i][8])setF(i,8,0);}
for(let i=0;i<8;i++){if(!reserved[8][size-1-i])setF(8,size-1-i,0);if(!reserved[size-1-i][8])setF(size-1-i,8,0);}
setF(8,size-8,1);
// place data
let bitIdx=0;let up=true;
for(let col=size-1;col>0;col-=2){if(col===6)col--;for(let k=0;k<size;k++){const row=up?size-1-k:k;for(const cc of [col,col-1]){if(!reserved[row][cc]){const b=bitIdx<codewords.length*8?((codewords[bitIdx>>3]>>(7-(bitIdx&7)))&1):0;matrix[row][cc]=b;bitIdx++;}}}up=!up;}
// format info (mask 0, ECC bits)
const fmtMap={L:1,M:0,Q:3,H:2};const ecBits=fmtMap[ecLevel];
let fmt=(ecBits<<3)|0;let f=fmt<<10;for(let i=14;i>=10;i--){if((f>>i)&1)f^=(0x537<<(i-10));}fmt=((fmt<<10)|f)^0x5412;
for(let i=0;i<=5;i++)matrix[8][i]=((fmt>>i)&1);matrix[8][7]=((fmt>>6)&1);matrix[8][8]=((fmt>>7)&1);matrix[7][8]=((fmt>>8)&1);for(let i=9;i<15;i++)matrix[14-i][8]=((fmt>>i)&1);
for(let i=0;i<8;i++)matrix[size-1-i][8]=((fmt>>i)&1);for(let i=8;i<15;i++)matrix[8][size-15+i]=((fmt>>i)&1);matrix[size-8][8]=1;
return matrix;}

function toCanvas(text,canvas,opts){opts=opts||{};const ec=opts.ecLevel||'M';const size=opts.width||256;const margin=opts.margin!==undefined?opts.margin:4;
const m=encodeData(text,ec);const n=m.length;const tile=(size-margin*2)/n;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle=opts.light||'#ffffff';ctx.fillRect(0,0,size,size);ctx.fillStyle=opts.dark||'#000000';
for(let y=0;y<n;y++)for(let x=0;x<n;x++){if(m[y][x])ctx.fillRect(Math.floor(margin+x*tile),Math.floor(margin+y*tile),Math.ceil(tile),Math.ceil(tile));}}
global.QRCode={toCanvas};
})(typeof window!=='undefined'?window:this);